			["Wait until idle", "Stop and continue", "Cancel"],
			{ signal },
		);
		if (!choice || choice === "Cancel") return;
		if (choice === "Stop and continue") await requestSessionTransfer(file, { stop: true, timeoutMs: 30_000, signal });
		else {
