	startup: StartupMode;
}
export interface GatewayRuntimeStatus {
	version: 1;
	instance: string;
	pid: number;
	startedAt: string;
	updatedAt: string;
	state: "starting" | "ready" | "stopping";
	platforms: Record<string, string>;
}
const servicePrefix = "lunr-gateway";
export const serviceDirectory = () => join(getAgentDir(), "gateway-service");
