	cancelSessionHandoff,
	HANDOFF_DURATION_MS,
	latestTuiSession,
	listHandoffCandidates,
	listRegisteredSessionPaths,
	markSessionHandoff,
	recordTuiActivity,
	registerTransferHandler,
